import { customType, timestamp, uuid } from "drizzle-orm/pg-core";
import { sql, type SQL, type AnyColumn } from "drizzle-orm";
import { uuidv7 } from "../kernel/ids";

/** Case-insensitive text (docs/03 §3.1: email, slug). Requires the citext extension (migration 0000). */
export const citext = customType<{ data: string }>({
  dataType: () => "citext",
});

export const tsvector = customType<{ data: string }>({
  dataType: () => "tsvector",
});

/** UUIDv7 primary key generated by the application. */
export const pk = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
export const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdateFn(() => new Date());

export const tstz = (name: string) => timestamp(name, { withTimezone: true });

/** `col in ('a','b',…)` for CHECK constraints built from the shared enum lists. */
export function inList(col: AnyColumn | SQL, values: readonly string[]): SQL {
  const list = values.map((v) => `'${v.replace(/'/g, "''")}'`).join(", ");
  return sql`${col} in (${sql.raw(list)})`;
}
